/* Shared shell for every inner page: top nav, sidebar, on-page contents, pager, comments.
   Pages are listed from assets/nav.js, which build.py generates. */

/* SITE (the sidebar list) is generated by build.py into assets/nav.js from the published pages. */

/* Comments use giscus (GitHub Discussions). Fill these in from https://giscus.app
   once a PUBLIC repository with Discussions enabled exists. Empty = show the fallback. */
const GISCUS = { repo: '', repoId: '', category: 'Ideas', categoryId: '' };

const EMAIL = 'edu.borjkhani@gmail.com';
const GITHUB = 'https://github.com/Hadi-Borjkhani';

(() => {
  const here = location.pathname.replace(/index\.html$/, '');
  const flat = SITE.flatMap(g => g.items);

  // top nav
  const nav = document.createElement('nav');
  nav.className = 'nav'; nav.setAttribute('aria-label', 'Main');
  const label = { projects: 'Projects', ideas: 'Ideas', lab: 'Lab' };
  const top = SITE.map(g => [label[g.key] || g.group, g.items[0][1], '/' + g.key + '/']).concat([['Contact', '/#contact', '#']]);
  nav.innerHTML = `<button class="menu" aria-expanded="false" aria-controls="sidebar">Menu</button>
    <a class="mark" href="/">H. Borjkhani</a>
    <ul>${top.map(([t, h, p]) => `<li><a href="${h}"${here.startsWith(p) ? ' aria-current="page"' : ''}>${t}</a></li>`).join('')}</ul>`;
  document.body.prepend(nav);

  // sidebar
  const sb = document.getElementById('sidebar');
  if (sb) {
    sb.innerHTML = `<input type="search" placeholder="Filter pages…" aria-label="Filter pages">` +
      SITE.map(g => `<div class="grp">${g.group}</div><ul>${g.items.map(([t, h]) =>
        `<li><a href="${h}"${h === here ? ' aria-current="page"' : ''}>${t}</a></li>`).join('')}</ul>`).join('');
    sb.querySelector('input').addEventListener('input', e => {
      const q = e.target.value.toLowerCase();
      sb.querySelectorAll('li').forEach(li => li.classList.toggle('hide', !li.textContent.toLowerCase().includes(q)));
    });
    const btn = nav.querySelector('.menu');
    btn.addEventListener('click', () => { const o = sb.classList.toggle('open'); btn.setAttribute('aria-expanded', o); });
  }

  // on-page contents with scroll spy
  const toc = document.getElementById('toc');
  const heads = [...document.querySelectorAll('.article h2[id]')];
  if (toc && heads.length) {
    toc.innerHTML = `<div class="grp">On this page</div>` + heads.map(h => `<a href="#${h.id}">${h.textContent}</a>`).join('');
    const links = [...toc.querySelectorAll('a')];
    const spy = () => {
      let i = heads.findLastIndex(h => h.getBoundingClientRect().top < 120);
      links.forEach((a, k) => a.classList.toggle('on', k === Math.max(i, 0)));
    };
    addEventListener('scroll', spy, { passive: true }); spy();
  }

  // previous / next
  const art = document.querySelector('.article');
  const idx = flat.findIndex(([, h]) => h === here);
  if (art && idx >= 0) {
    const prev = flat[idx - 1], next = flat[idx + 1];
    const pg = document.createElement('div'); pg.className = 'pager';
    pg.innerHTML = (prev ? `<a href="${prev[1]}">← Previous<b>${prev[0]}</b></a>` : '') +
                   (next ? `<a class="next" href="${next[1]}">Next →<b>${next[0]}</b></a>` : '');
    art.append(pg);
  }

  // discussion block on pages that ask for it
  const d = document.getElementById('discuss');
  if (d) {
    const topic = document.querySelector('.article h1')?.textContent || document.title;
    d.className = 'discuss';
    d.innerHTML = `<h2 id="discussion">Discussion</h2>
      <p>Questions, criticism, or a related result from your own lab? Leave it here. I read every comment.</p>`;
    if (GISCUS.repo && GISCUS.repoId && GISCUS.categoryId) {
      const s = document.createElement('script');
      s.src = 'https://giscus.app/client.js'; s.async = true; s.crossOrigin = 'anonymous';
      Object.entries({ repo: GISCUS.repo, 'repo-id': GISCUS.repoId, category: GISCUS.category, 'category-id': GISCUS.categoryId,
        mapping: 'pathname', strict: '0', 'reactions-enabled': '1', 'emit-metadata': '0', 'input-position': 'top',
        theme: 'transparent_dark', lang: 'en', loading: 'lazy' }).forEach(([k, v]) => s.setAttribute('data-' + k, v));
      d.append(s);
    } else {
      const sub = encodeURIComponent('Re: ' + topic);
      d.insertAdjacentHTML('beforeend', `<div class="fallback">Comments open here soon. Until then, write to
        <a href="mailto:${EMAIL}?subject=${sub}">${EMAIL}</a> or find me on <a href="${GITHUB}">GitHub</a>.</div>`);
    }
  }
})();

/* ---------- tiny chart helpers shared by the interactive pages ---------- */
const Plot = {
  svg(el, w, h) {
    el.innerHTML = `<svg viewBox="0 0 ${w} ${h}" role="img"></svg><div class="tip"></div>`;
    return { svg: el.querySelector('svg'), tip: el.querySelector('.tip') };
  },
  ns: 'http://www.w3.org/2000/svg',
  el(parent, tag, attrs = {}, text) {
    const e = document.createElementNS(Plot.ns, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (text != null) e.textContent = text;
    parent.append(e); return e;
  },
  log(d0, d1, r0, r1) { const a = Math.log10(d0), b = Math.log10(d1); const f = v => r0 + (Math.log10(v) - a) / (b - a) * (r1 - r0); f.inv = p => 10 ** (a + (p - r0) / (r1 - r0) * (b - a)); return f; },
  lin(d0, d1, r0, r1) { const f = v => r0 + (v - d0) / (d1 - d0) * (r1 - r0); f.inv = p => d0 + (p - r0) / (r1 - r0) * (d1 - d0); return f; },
  si(v, unit) {
    const pre = [[1e-15, 'f'], [1e-12, 'p'], [1e-9, 'n'], [1e-6, 'µ'], [1e-3, 'm'], [1, ''], [1e3, 'k']];
    let p = pre[0]; for (const q of pre) if (Math.abs(v) >= q[0]) p = q;
    const x = v / p[0]; return (x >= 100 ? x.toFixed(0) : x >= 10 ? x.toFixed(1) : x.toFixed(2)) + ' ' + p[1] + unit;
  },
  showTip(tip, host, x, y, html) {
    tip.innerHTML = html; tip.classList.add('on');
    const r = host.getBoundingClientRect(), tw = tip.offsetWidth;
    tip.style.left = Math.min(Math.max(x + 14, 0), r.width - tw - 4) + 'px';
    tip.style.top = Math.max(y - 10 - tip.offsetHeight, 0) + 'px';
  },
};
